  if (!head || !research || !articles) return;
  const esc = t => String(t).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
  const el = (tag, cls, html) => { const e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; };
  const STEPS = ["The question", "Connected evidence", "Intelligence Gap", "SavoScouts investigate", "Verified findings", "Decision to test"];

  /* ---------- Case studies section ---------- */
  const cs = el("section", "cs-sec");
  cs.setAttribute("aria-labelledby", "cs-h");
