  /* deep link from the Product page: ?case=<id>#research opens that case study */
  let deep = null;
  try { deep = new URLSearchParams(location.search).get("case"); } catch (e) {}
  if (deep && CS_DATA.cases.some(x => x.id === deep)) { if (!ucMount) first = "cases"; } else deep = null;
  select(panels[first] ? first : "research", false);
  window.vsResearchTab = k => { if (k === "cases" && ucMount) { if (window.vsGoPage) window.vsGoPage("use-cases"); return; } select(panels[k] ? k : "research", false); };
  window.vsCases = CS_DATA.cases;
